#include "array_suffix.hpp"
#include <cstddef>
#include <vector>
#include "keywords.hpp"
#include "tokens.hpp"

using blitz::tools::kind;
using blitz::tools::token;

std::string blitz::format::remove_array_suffixes(std::string const& source)
{
	auto tokens = blitz::tools::tokenize(source);

	// The tokens that are not white space or comments, by their place in 'tokens'.
	std::vector<size_t> sig;
	for (size_t i = 0; i < tokens.size(); i++) {
		if (!tokens[i].is(kind::space) && !tokens[i].is(kind::comment)) {
			sig.push_back(i);
		}
	}
	auto word = [&](size_t s, const char* lower) { return tokens[sig[s]].is(kind::word) && (blitz::tools::lower(tokens[sig[s]].text) == lower); };
	auto type_colon = [&](size_t s) {
		// x:Int32 has a : that touches a name and a type name, which is no separator.
		size_t i = sig[s];
		return (i > 0) && (i + 1 < tokens.size()) && tokens[i - 1].is(kind::word) && tokens[i + 1].is(kind::word) && blitz::tools::is_type_name(tokens[i + 1].text);
	};

	std::vector<bool> drop(tokens.size(), false);
	bool              declaring = false; // The statement is a Local, Global, Field, Const or Dim.
	bool              start     = true;
	int               depth     = 0;
	for (size_t s = 0; s < sig.size(); s++) {
		auto const& t = tokens[sig[s]];
		if (t.is(kind::newline) || (t.is(kind::separator) && !type_colon(s))) {
			start = true;
			declaring = false;
			depth     = 0;
			continue;
		}
		if (start) {
			declaring = word(s, "local") || word(s, "global") || word(s, "field") || word(s, "const") || word(s, "dim");
		}
		bool was_start = start;
		start          = word(s, "then") || word(s, "else");
		if (start) {
			declaring = false;
		}
		depth += (t.is_symbol("(") || t.is_symbol("[")) ? 1 : ((t.is_symbol(")") || t.is_symbol("]")) ? -1 : 0);
		if (!t.is(kind::word) || (was_start && declaring)) {
			continue;
		}
		// A name in a declaration (behind the keyword, or a comma between the declared names), and a field (behind a \), keep it.
		if (!was_start) {
			auto const& prev          = tokens[sig[s - 1]];
			bool        after_keyword = word(s - 1, "local") || word(s - 1, "global") || word(s - 1, "field") || word(s - 1, "const") || word(s - 1, "dim");
			bool        named         = declaring && (depth == 0) && (prev.is_symbol(",") || after_keyword);
			if (named || prev.is_symbol("\\") || prev.is_symbol(".")) {
				continue;
			}
		}
		char last = t.text.back();
		if (((last == '%') || (last == '#') || (last == '$')) && (s + 1 < sig.size()) && tokens[sig[s + 1]].is_symbol("[")) {
			// Name#[...]: the type character is part of the word.
			size_t keep = t.text.find_first_of("%#$");
			if ((keep != std::string::npos) && (keep > 0)) {
				tokens[sig[s]].text = t.text.substr(0, keep);
			}
		} else if ((s + 3 < sig.size()) && tokens[sig[s + 1]].is_symbol(".") && (sig[s + 1] == sig[s] + 1) && tokens[sig[s + 2]].is(kind::word) && (sig[s + 2] == sig[s + 1] + 1) && tokens[sig[s + 3]].is_symbol("[")) {
			// Name.Type[...]
			drop[sig[s + 1]] = true;
			drop[sig[s + 2]] = true;
		}
	}

	std::string out;
	for (size_t i = 0; i < tokens.size(); i++) {
		if (!drop[i]) {
			out += tokens[i].text;
		}
	}
	return out;
}
